// Build-time contract for the critical-CSS bundles: the generated modules are
// build outputs, not sources. They must stay out of git (ignored + untracked)
// so style PRs stop conflicting on derived bytes, and every install must
// regenerate them so typecheck/tests/bundlers always see fresh bytes.
// test/leaf-css-drift.test.ts remains the gate that the generated bytes equal
// the committed sources; this file pins the out-of-git wiring around it.
import { execFileSync, spawnSync } from "node:child_process";
import { mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const git = (args: string[]) => execFileSync("git", args, { cwd: root, encoding: "utf8" });
const scriptsOf = (rel: string) =>
  (JSON.parse(readFileSync(resolve(root, rel), "utf8")) as { scripts?: Record<string, string> })
    .scripts ?? {};

describe("critical CSS is a build output, not a source", () => {
  it("ignores the generated bundles so style PRs never touch derived bytes", () => {
    for (const bundle of ["src/leaf-critical-css.ts", "src/home-critical-css.ts"]) {
      let ignored = false;
      try {
        // Test ignore policy independently of another branch tracking a future bundle.
        // The separate assertion below owns this PR's leaf untracking contract.
        git(["check-ignore", "--no-index", "-q", bundle]);
        ignored = true;
      } catch {
        ignored = false;
      }
      expect(ignored, `${bundle} must be git-ignored`).toBe(true);
    }
  });

  it("does not track the generated leaf bundle", () => {
    expect(
      git(["ls-files", "src/leaf-critical-css.ts"]).trim(),
      "git rm --cached src/leaf-critical-css.ts",
    ).toBe("");
  });

  it("regenerates the bundle on every root install", () => {
    expect(scriptsOf("package.json").postinstall ?? "").toContain("build-leaf-css");
  });

  it("exposes an explicit rebuild script", () => {
    expect(scriptsOf("package.json")["build:leaf-css"] ?? "").toContain("ci/build-leaf-css.mjs");
  });

  it("regenerates the bundle before every local dev server start", () => {
    expect(scriptsOf("package.json").predev ?? "").toContain("ci/build-leaf-css.mjs");
  });

  it("regenerates the bundle before every Kit build", () => {
    expect(scriptsOf("web/package.json").prebuild ?? "").toContain("ci/build-leaf-css.mjs");
  });

  it("checks token adapters before every Kit build", () => {
    expect(scriptsOf("web/package.json").build ?? "").toContain(
      "ci/build-ember-tokens.mjs --check",
    );
  });

  it("checks token adapters before every Kit check", () => {
    expect(scriptsOf("web/package.json").check ?? "").toContain(
      "ci/build-ember-tokens.mjs --check",
    );
  });

  it("regenerates the bundle on every Kit install", () => {
    expect(scriptsOf("web/package.json").postinstall ?? "").toContain("build-leaf-css");
  });

  it.each(["build", "check"])(
    "checks tokens and regenerates missing and stale CSS before Kit %s with lifecycle hooks disabled",
    (command) => {
      const fixture = mkdtempSync(join(tmpdir(), "kit-css-lifecycle-"));
      try {
        for (const dir of ["ci", "public", "src", "web", "web/node_modules/.bin"]) {
          mkdirSync(join(fixture, dir), { recursive: true });
        }
        writeFileSync(
          join(fixture, "ci/build-leaf-css.mjs"),
          readFileSync(join(root, "ci/build-leaf-css.mjs")),
        );
        writeFileSync(
          join(fixture, "ci/build-events-css.mjs"),
          readFileSync(join(root, "ci/build-events-css.mjs")),
        );
        writeFileSync(
          join(fixture, "ci/build-ember-tokens.mjs"),
          `import { writeFileSync } from "node:fs";\nimport { dirname, join } from "node:path";\nimport { fileURLToPath } from "node:url";\nconst dir = dirname(fileURLToPath(import.meta.url));\nwriteFileSync(join(dir, "..", "ember-tokens-checked.txt"), "checked");\n`,
        );
        for (const source of [
          "styles.css",
          "theme-tokens.css",
          "theme.css",
          "schedule-theme.css",
        ]) {
          writeFileSync(join(fixture, "public", source), ":root { color: red; }");
        }
        writeFileSync(
          join(fixture, "web/package.json"),
          readFileSync(join(root, "web/package.json")),
        );
        writeFileSync(join(fixture, "web/.npmrc"), readFileSync(join(root, "web/.npmrc")));
        // Stop at the bundler/typechecker boundary; no dependencies or build are needed.
        for (const binary of ["vite", "svelte-kit"]) {
          writeFileSync(join(fixture, "web/node_modules/.bin", binary), "#!/bin/sh\nexit 42\n", {
            mode: 0o755,
          });
        }
        const output = join(fixture, "src/leaf-critical-css.ts");
        const eventsOutput = join(fixture, "src/events-critical-css.ts");
        for (const initial of [null, "stale CSS"]) {
          if (initial !== null) {
            writeFileSync(output, initial);
            writeFileSync(eventsOutput, initial);
          }
          const result = spawnSync("npm", ["run", command, "--prefix", join(fixture, "web")], {
            cwd: fixture,
            encoding: "utf8",
            env: { ...process.env, npm_config_ignore_scripts: "true" },
            timeout: 10_000,
          });
          expect(result.status, `${result.stdout}\n${result.stderr}`).toBe(42);
          expect(readFileSync(join(fixture, "ember-tokens-checked.txt"), "utf8")).toBe("checked");
          expect(readFileSync(output, "utf8")).toContain(":root { color: red; }");
          expect(readFileSync(output, "utf8")).not.toContain("stale CSS");
          expect(readFileSync(eventsOutput, "utf8")).toContain(":root { color: red; }");
          expect(readFileSync(eventsOutput, "utf8")).not.toContain("stale CSS");
        }
      } finally {
        rmSync(fixture, { recursive: true, force: true });
      }
    },
  );
});
